import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.1lnE8eph.js";const u=JSON.parse('{"title":"Historical Specification: Flexbox Module Resizing","description":"","frontmatter":{},"headers":[],"relativePath":"specs/007-legacy-flexbox-module-resizing.md","filePath":"specs/007-legacy-flexbox-module-resizing.md"}'),r={name:"specs/007-legacy-flexbox-module-resizing.md"};function s(o,e,l,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="historical-specification-flexbox-module-resizing" tabindex="-1">Historical Specification: Flexbox Module Resizing <a class="header-anchor" href="#historical-specification-flexbox-module-resizing" aria-label="Permalink to &quot;Historical Specification: Flexbox Module Resizing&quot;">​</a></h1><h2 id="status-and-precedence" tabindex="-1">Status and precedence <a class="header-anchor" href="#status-and-precedence" aria-label="Permalink to &quot;Status and precedence&quot;">​</a></h2><ul><li>Status: historical baseline for architectural research, not a request to restore this implementation.</li><li>Derived from the <a href="https://airafa.github.io/bus-map-table-docs/guide/module-resizing.html" target="_blank" rel="noreferrer">published historical guide</a>.</li><li>Superseded for current pane resizing by <a href="./008-hybrid-grid-module-resizing">Hybrid Grid Module Resizing</a>.</li><li>The original walkthrough remains in the table documentation; its duplicate application-root file has been removed in favor of this specification.</li><li>Requirements below describe the historical contract. They must not be mixed into the current Grid implementation.</li></ul><h2 id="_1-scope" tabindex="-1">1. Scope <a class="header-anchor" href="#_1-scope" aria-label="Permalink to &quot;1. Scope&quot;">​</a></h2><p>Resize adjacent application layout panels through the starterkit&#39;s existing recursive layout state and Flexbox sizing. Support native pointer and keyboard input without adding a splitter library.</p><p>Module-pane resizing is separate from table-column resizing and the editor&#39;s module/layout drag-and-drop.</p><h2 id="_2-layout-configuration-and-identity" tabindex="-1">2. Layout configuration and identity <a class="header-anchor" href="#_2-layout-configuration-and-identity" aria-label="Permalink to &quot;2. Layout configuration and identity&quot;">​</a></h2><ul><li>LF-01: A resizable parent shall declare <code>resizable.minPercent</code> and <code>resizable.maxPercent</code>.</li><li>LF-02: Limits shall be finite and satisfy <code>0 &lt; minPercent &lt;= maxPercent &lt; 100</code>.</li><li>LF-03: The historical dashboard shall start with a 25:75 schedule/map split and allow a first-pane share of 25% through 75%.</li><li>LF-04: Resized siblings shall be layout-panel wrappers with stable UUIDs and positive finite flex-grow weights using a zero-basis sizing contract.</li><li>LF-05: Panels shall expose <code>data-layout-id={uuid}</code> for DOM lookup. Raw module siblings are not a supported replacement for these wrappers.</li><li>LF-06: Modules shall retain their existing container assignments and mount lifecycle.</li></ul><h2 id="_3-recursive-rendering-and-state-ownership" tabindex="-1">3. Recursive rendering and state ownership <a class="header-anchor" href="#_3-recursive-rendering-and-state-ownership" aria-label="Permalink to &quot;3. Recursive rendering and state ownership&quot;">​</a></h2><ul><li>LF-07: For an enabled parent&#39;s <code>layout.items</code>, the renderer shall insert one separator between each adjacent pair without adding a wrapper DOM element. Three panels therefore have two separators.</li><li>LF-08: Separators shall remain presentation elements, not persisted layout nodes or entries in the editor tree.</li><li>LF-09: Each separator shall receive the parent, preceding panel, following panel, and parent UUID path.</li><li>LF-10: Child update paths shall include the root UUID and append the affected panel UUID. Traversal shall respect the existing layout service&#39;s root-relative conventions.</li><li>LF-11: Each handled movement or keyboard update shall commit the two affected flex styles through <code>updateLayout</code>, preserving existing node and style fields. Imperative width changes shall not replace authoritative layout updates.</li><li>LF-12: The implementation shall preserve the existing service&#39;s notifications. Consumers shall not assume atomic pair updates or a specific <code>UPDATE_LAYOUT</code> event: the historical service uses two calls and wildcard notifications.</li></ul><h2 id="_4-resize-calculation" tabindex="-1">4. Resize calculation <a class="header-anchor" href="#_4-resize-calculation" aria-label="Permalink to &quot;4. Resize calculation&quot;">​</a></h2><p>For adjacent weights <code>a</code> and <code>b</code>, starting coordinate <code>c0</code>, current coordinate <code>c</code>, and combined measured pane size <code>S</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>total = a + b</span></span>
<span class="line"><span>startPercent = a / total * 100</span></span>
<span class="line"><span>sign = -1 for a reverse flex direction, otherwise 1</span></span>
<span class="line"><span>requested = startPercent + (c - c0) / S * 100 * sign</span></span>
<span class="line"><span>bounded = min(maxPercent, max(minPercent, requested))</span></span>
<span class="line"><span>newA = total * bounded / 100</span></span>
<span class="line"><span>newB = total - newA</span></span></code></pre></div><ul><li>LF-13: Measure the two panes at pointer down and exclude separator space by using their combined dimensions.</li><li>LF-14: Preserve the adjacent pair&#39;s total weight and leave other sibling weights unchanged.</li><li>LF-15: Read orientation from the parent&#39;s configured inline <code>flexDirection</code>; use X for rows and Y for columns.</li><li>LF-16: Invert physical movement for <code>row-reverse</code> and <code>column-reverse</code>.</li><li>LF-17: Write normalized zero-basis flex shorthand, preserving unrelated style.</li></ul><p>Historical parsing uses <code>Number.parseFloat(style.flex) || 1</code>. Missing, nonnumeric, or zero values become 1; negative values and arbitrary flex keywords are outside the supported contract. This is a recorded limitation, not a recommendation to weaken input validation in a new implementation.</p><h2 id="_5-interaction-and-accessibility" tabindex="-1">5. Interaction and accessibility <a class="header-anchor" href="#_5-interaction-and-accessibility" aria-label="Permalink to &quot;5. Interaction and accessibility&quot;">​</a></h2><ul><li>LF-18: Only primary-button pointer input shall start resizing.</li><li>LF-19: The separator shall capture the pointer, prevent selection, and avoid triggering editor selection/drag behavior.</li><li>LF-20: Pointer up, pointer cancellation, and lost capture shall clear active drag state. There is no separate completion-only persistence step: movement has already updated shared layout state.</li><li>LF-21: Render a focusable separator with an accessible name, orientation, configured minimum/maximum, and current pair percentage.</li><li>LF-22: Applicable arrow keys shall change the first pane by two percentage points. Reverse flex directions shall invert physical arrow behavior.</li><li>LF-23: Home and End shall select the configured minimum and maximum.</li><li>LF-24: Use <code>touch-action: none</code>, an axis-appropriate resize cursor, a visible focus indicator, and nonselectable separator content.</li><li>LF-25: Allow panes to shrink with appropriate zero minimum width/height. Tables, maps, and canvases shall adapt to host size or scroll as intended.</li></ul><p>Inherited RTL direction is not fully supported by this historical algorithm. Reverse-flex handling shall not be represented as complete RTL support.</p><h2 id="_6-editor-persistence-and-offline-behavior" tabindex="-1">6. Editor, persistence, and offline behavior <a class="header-anchor" href="#_6-editor-persistence-and-offline-behavior" aria-label="Permalink to &quot;6. Editor, persistence, and offline behavior&quot;">​</a></h2><ul><li>LF-26: Editor properties and separators shall operate on the same layout styles. Editing Flex shall affect the next interaction.</li><li>LF-27: Resizing shall remain available outside editor mode and in production. Existing permitted editor drop targets shall keep working.</li><li>LF-28: A full reload shall restore configuration defaults unless a destination separately implements persistence. This historical feature adds neither browser storage nor network preference requests.</li><li>LF-29: Porting shall reuse the destination&#39;s layout provider, state service, versions, and module boundaries rather than replace them.</li><li>LF-30: Air-gapped installation shall use authorized offline dependency artifacts without copying registry credentials. Offline builds shall not be represented as guaranteeing offline map tiles or external services.</li></ul><h2 id="_7-acceptance-criteria" tabindex="-1">7. Acceptance criteria <a class="header-anchor" href="#_7-acceptance-criteria" aria-label="Permalink to &quot;7. Acceptance criteria&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Scenario</th><th>Expected result</th></tr></thead><tbody><tr><td>LA-01</td><td>Weights 25 and 75, combined pane width 1,000px, LTR movement +100px</td><td>Weights become approximately 35 and 65</td></tr><tr><td>LA-02</td><td>Request below/above configured range</td><td>Clamp to configured limits</td></tr><tr><td>LA-03</td><td>Weights 2, 3, 5; set first pair to 60%</td><td>Weights become 3, 2, 5</td></tr><tr><td>LA-04</td><td>Resize a nested group</td><td>Only the intended UUID paths change</td></tr><tr><td>LA-05</td><td>Column or reverse-direction layout</td><td>Correct axis and inversion</td></tr><tr><td>LA-06</td><td>Tab, arrows, Home, End</td><td>Accessible state and two-point steps match weights</td></tr><tr><td>LA-07</td><td>Pointer leaves handle, then releases/cancels</td><td>Capture maintains movement; active state clears</td></tr><tr><td>LA-08</td><td>Edit Flex, disable editor, then resize</td><td>Updated model is used; resizing remains enabled</td></tr><tr><td>LA-09</td><td>Reload without separately added persistence</td><td>Configuration defaults return</td></tr><tr><td>LA-10</td><td>Observe network during resizing</td><td>No resize-generated requests</td></tr><tr><td>LA-11</td><td>Use existing editor DnD and heavy content</td><td>Placement behavior remains; content adapts or scrolls</td></tr></tbody></table><p>Use the runnable arithmetic check and interaction checklist in the <a href="https://airafa.github.io/bus-map-table-docs/guide/module-resizing.html" target="_blank" rel="noreferrer">published historical guide</a> when researching this version. Current Grid tests do not establish that the removed historical renderer still exists or passes these criteria.</p><h2 id="_8-recorded-limitations-and-non-goals" tabindex="-1">8. Recorded limitations and non-goals <a class="header-anchor" href="#_8-recorded-limitations-and-non-goals" aria-label="Permalink to &quot;8. Recorded limitations and non-goals&quot;">​</a></h2><ul><li>No animation-frame throttling or atomic pair update.</li><li>No dedicated simultaneous-pointer arbitration.</li><li>No automatic initial normalization of out-of-range imported weights.</li><li>No CSS-only orientation detection or complete inherited RTL support.</li><li>Geometry is assumed stable during a gesture.</li><li>Limits are pair percentages, not pixel minimums.</li><li>No built-in responsive breakpoint, preference persistence, undo, snapping, collapsing, or double-click reset.</li><li>Shared layout rerenders on movement can be expensive with heavy descendants.</li></ul><p>These ceilings are part of the research baseline; they are not current feature requirements.</p>`,26)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
